script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({api, event}) {
    var subHeadingList = [];
    if (api.data.lp_card.result) {
        var title = api.data.lp_card.result.title ? api.data.lp_card.result.title.displayValue : '';
        var department = api.data.lp_card.result.department ? api.data.lp_card.result.department.displayValue : '';

        if (title) subHeadingList.push(title);
        if (department) subHeadingList.push(department);
    }

    return {
        viewportElementId: "viewport_glu",
        route: "caller-contact",
        fields: {
            "table": api.context.props.recordTable,
            "recordSysId": api.context.props.recordSysId,
            "userSysId": api.context.props.userSysId
        },
        params: {
            "subTitle": subHeadingList.join(' · '),
            "parent": "record-info-incident",
            "isCtiEnabled": api.data.record.isCtiEnabled
        }
    };
}

